mapper.select:
SELECT n.*,
       u.nickname AS publisher_name
FROM sys_notice n
LEFT JOIN sys_user u ON u.id = n.publisher AND u.is_deleted = 0
WHERE n.is_deleted = 0
AND n.tenant_id = #{tenantId}

    AND (n.title LIKE CONCAT('%', #{request.keyword}, '%')
         OR n.content LIKE CONCAT('%', #{request.keyword}, '%'))


    AND n.type = #{request.type}


    AND n.level = #{request.level}


    AND n.status = #{request.status}



        ORDER BY ${request.safeSortField()} ${request.safeSortOrder()}


        ORDER BY n.is_top DESC, n.sort ASC, n.publish_time DESC, n.create_time DESC

mapper.sql:
n.is_deleted = 0
AND n.tenant_id = #{tenantId}
AND n.status = 'published'
AND (n.effective_time IS NULL OR n.effective_time <= NOW())
AND (n.expire_time IS NULL OR n.expire_time >= NOW())
AND (
    n.target_type = 'all'
    OR EXISTS (
        SELECT 1 FROM sys_notice_target t
        WHERE t.is_deleted = 0
        AND t.notice_id = n.id
        AND (
            (n.target_type = 'user' AND t.target_type = 'user' AND t.target_id = #{userId})
            OR (n.target_type = 'dept' AND t.target_type = 'dept' AND t.target_id IN
                #{deptId}
            )
            OR (n.target_type = 'role' AND t.target_type = 'role' AND t.target_id IN
                #{roleId}
            )
        )
    )
)

